-- 00000000000026_specialized_guides.sql — stored legal-reference data with its source
--
-- 1. hague_central_authorities / hague_resources
--    The Hague screen used to show a country list hard-coded in the app and an
--    authority list hard-coded in the server. Both now come from these tables,
--    each row with the source it was recorded from, when it was recorded and
--    when (if ever) someone checked it again (last_verified_at NULL = never).
--    The rows are copied exactly as they were recorded in
--    backend/src/routes/hague_contacts.js on 2026-05-30 — nothing was added,
--    removed or "corrected". Several rows need a lawyer's review (see
--    notes/debug_pass.md section F).
-- 2. content_translations
--    Database text that people read (specialty-court eligibility / notes) is
--    English. Translations are stored next to it with the md5 of the English
--    text they were made from: the API serves a translation only while the
--    English still matches, so the English stays the source of truth and an
--    edited row falls back to English instead of showing an outdated text.
--
-- Idempotent: CREATE TABLE IF NOT EXISTS, INSERT … ON CONFLICT DO NOTHING.

CREATE TABLE IF NOT EXISTS hague_central_authorities (
  country_code     TEXT PRIMARY KEY CHECK (country_code ~ '^[A-Z]{2}$'),
  country_name     TEXT NOT NULL,
  authority_name   TEXT NOT NULL,
  website          TEXT,
  phone            TEXT,
  emergency_phone  TEXT,
  email            TEXT,
  hours_note       TEXT,
  contracting      BOOLEAN NOT NULL,
  source           TEXT NOT NULL,
  source_url       TEXT,
  recorded_at      DATE NOT NULL,
  last_verified_at DATE
);
ALTER TABLE hague_central_authorities ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS hague_resources (
  key              TEXT PRIMARY KEY,
  name             TEXT NOT NULL,
  phone            TEXT,
  website          TEXT,
  statute          TEXT,
  source           TEXT NOT NULL,
  source_url       TEXT,
  recorded_at      DATE NOT NULL,
  last_verified_at DATE,
  sort_order       INTEGER NOT NULL DEFAULT 0
);
ALTER TABLE hague_resources ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS content_translations (
  table_name  TEXT NOT NULL,
  row_id      BIGINT NOT NULL,
  field       TEXT NOT NULL,
  lang        TEXT NOT NULL CHECK (lang IN ('es', 'pt', 'vi')),
  text        TEXT NOT NULL,
  source_md5  TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (table_name, row_id, field, lang)
);
ALTER TABLE content_translations ENABLE ROW LEVEL SECURITY;

ON CONFLICT (country_code) DO NOTHING;

ON CONFLICT (key) DO NOTHING;

-- Specialty-court eligibility and notes (rows 1–30 of migration 01), es / pt-BR / vi
ON CONFLICT (table_name, row_id, field, lang) DO NOTHING;
