INSERT INTO content_translations (table_name, row_id, field, lang, text, source_md5)
VALUES
  ('specialty_courts', 1, 'eligibility', 'es', 'Miembro en servicio activo, veterano o miembro de la Guardia Nacional o la Reserva. Cargo penal relacionado con TEPT, lesión cerebral traumática (TBI), trauma sexual militar (MST) o trastorno por consumo de sustancias vinculado al servicio.', md5('Active duty, veteran, or National Guard/Reserve member. Criminal charge related to service-connected PTSD, TBI, MST, or substance use disorder.')),
  ('specialty_courts', 1, 'notes', 'es', 'Se reúne cada dos jueves. Se requieren el DD-214 y documentos del VA al ingresar.', md5('Meets every other Thursday. DD-214 and VA documentation required at intake.')),
  ('specialty_courts', 1, 'eligibility', 'pt', 'Militar da ativa, veterano ou membro da Guarda Nacional ou da Reserva. Acusação criminal relacionada a TEPT, lesão cerebral traumática (TBI), trauma sexual militar (MST) ou transtorno por uso de substâncias ligado ao serviço.', md5('Active duty, veteran, or National Guard/Reserve member. Criminal charge related to service-connected PTSD, TBI, MST, or substance use disorder.')),
  ('specialty_courts', 1, 'notes', 'pt', 'Reúne-se a cada duas quintas-feiras. O DD-214 e documentos do VA são exigidos na admissão.', md5('Meets every other Thursday. DD-214 and VA documentation required at intake.')),
  ('specialty_courts', 1, 'eligibility', 'vi', 'Quân nhân tại ngũ, cựu chiến binh hoặc thành viên Vệ binh Quốc gia/Lực lượng Dự bị. Cáo buộc hình sự liên quan đến PTSD, chấn thương sọ não (TBI), sang chấn tình dục trong quân ngũ (MST) hoặc rối loạn sử dụng chất có liên quan đến quá trình phục vụ.', md5('Active duty, veteran, or National Guard/Reserve member. Criminal charge related to service-connected PTSD, TBI, MST, or substance use disorder.')),
  ('specialty_courts', 1, 'notes', 'vi', 'Họp cách tuần vào thứ Năm. Cần có DD-214 và giấy tờ của VA khi tiếp nhận.', md5('Meets every other Thursday. DD-214 and VA documentation required at intake.')),
  ('specialty_courts', 2, 'eligibility', 'es', 'Veterano con cualquier tipo de baja excepto deshonrosa. Debe tener una condición vinculada al servicio. Se aceptan cargos de delito grave o menor.', md5('Veteran with any discharge status except dishonorable. Must have service-connected condition. Felony or misdemeanor charge eligible.')),
  ('specialty_courts', 2, 'notes', 'es', 'Programa con sede en Memphis. Colabora con el Centro Médico del VA de Memphis.', md5('Memphis-based program. Partners with Memphis VA Medical Center.')),
  ('specialty_courts', 2, 'eligibility', 'pt', 'Veterano com qualquer tipo de baixa, exceto desonrosa. Deve ter uma condição ligada ao serviço. Acusações de crime grave ou contravenção são aceitas.', md5('Veteran with any discharge status except dishonorable. Must have service-connected condition. Felony or misdemeanor charge eligible.')),
  ('specialty_courts', 2, 'notes', 'pt', 'Programa sediado em Memphis. Parceria com o Centro Médico do VA de Memphis.', md5('Memphis-based program. Partners with Memphis VA Medical Center.')),
  ('specialty_courts', 2, 'eligibility', 'vi', 'Cựu chiến binh với mọi loại giải ngũ trừ giải ngũ bất danh dự. Phải có tình trạng liên quan đến quá trình phục vụ. Chấp nhận cáo buộc trọng tội hoặc khinh tội.', md5('Veteran with any discharge status except dishonorable. Must have service-connected condition. Felony or misdemeanor charge eligible.')),
  ('specialty_courts', 2, 'notes', 'vi', 'Chương trình đặt tại Memphis. Hợp tác với Trung tâm Y tế VA Memphis.', md5('Memphis-based program. Partners with Memphis VA Medical Center.')),
  ('specialty_courts', 3, 'eligibility', 'es', 'Veterano con una condición de salud mental o de consumo de sustancias vinculada al servicio que califique. Hay vía para delitos graves y para delitos menores.', md5('Veteran with qualifying service-connected mental health or substance use condition. Felony and misdemeanor track available.')),
  ('specialty_courts', 3, 'notes', 'es', 'Uno de los VTC más grandes del país. Coordinador a tiempo completo y red de mentores voluntarios.', md5('One of the largest VTCs in the nation. Full-time coordinator and volunteer mentor network.')),
  ('specialty_courts', 3, 'eligibility', 'pt', 'Veterano com uma condição de saúde mental ou de uso de substâncias ligada ao serviço que se qualifique. Há trilha para crimes graves e para contravenções.', md5('Veteran with qualifying service-connected mental health or substance use condition. Felony and misdemeanor track available.')),
  ('specialty_courts', 3, 'notes', 'pt', 'Um dos maiores VTCs do país. Coordenador em tempo integral e rede de mentores voluntários.', md5('One of the largest VTCs in the nation. Full-time coordinator and volunteer mentor network.')),
  ('specialty_courts', 3, 'eligibility', 'vi', 'Cựu chiến binh có tình trạng sức khỏe tâm thần hoặc sử dụng chất đủ điều kiện, liên quan đến quá trình phục vụ. Có lộ trình cho trọng tội và cho khinh tội.', md5('Veteran with qualifying service-connected mental health or substance use condition. Felony and misdemeanor track available.')),
  ('specialty_courts', 3, 'notes', 'vi', 'Một trong những VTC lớn nhất cả nước. Có điều phối viên toàn thời gian và mạng lưới cố vấn tình nguyện.', md5('One of the largest VTCs in the nation. Full-time coordinator and volunteer mentor network.')),
  ('specialty_courts', 4, 'eligibility', 'es', 'Cualquier veterano con una condición vinculada al servicio. La mayoría de los cargos penales califican, excepto homicidio capital.', md5('Any veteran with service-connected condition. Most criminal charges eligible except capital murder.')),
  ('specialty_courts', 4, 'notes', 'es', 'Los participantes se conectan con beneficios del VA, vivienda y servicios de empleo.', md5('Participants connect with VA benefits, housing, and employment services.')),
  ('specialty_courts', 4, 'eligibility', 'pt', 'Qualquer veterano com uma condição ligada ao serviço. A maioria das acusações criminais se qualifica, exceto homicídio capital.', md5('Any veteran with service-connected condition. Most criminal charges eligible except capital murder.')),
  ('specialty_courts', 4, 'notes', 'pt', 'Os participantes são encaminhados a benefícios do VA, moradia e serviços de emprego.', md5('Participants connect with VA benefits, housing, and employment services.')),
  ('specialty_courts', 4, 'eligibility', 'vi', 'Bất kỳ cựu chiến binh nào có tình trạng liên quan đến quá trình phục vụ. Hầu hết các cáo buộc hình sự đều đủ điều kiện, trừ tội giết người có thể bị tử hình.', md5('Any veteran with service-connected condition. Most criminal charges eligible except capital murder.')),
  ('specialty_courts', 4, 'notes', 'vi', 'Người tham gia được kết nối với phúc lợi VA, nhà ở và dịch vụ việc làm.', md5('Participants connect with VA benefits, housing, and employment services.')),
  ('specialty_courts', 5, 'eligibility', 'es', 'Veterano o militar en servicio activo con un problema vinculado al servicio. Vía para delitos graves y vía para delitos menores.', md5('Veteran or active duty military with service-connected issue. Felony track and misdemeanor track.')),
  ('specialty_courts', 5, 'notes', 'es', 'El VTC más grande de California. Colabora con el VA de West LA y varias organizaciones de servicio a veteranos (VSO).', md5('Largest VTC in California. Partners with West LA VA and multiple VSOs.')),
  ('specialty_courts', 5, 'eligibility', 'pt', 'Veterano ou militar da ativa com um problema ligado ao serviço. Trilha para crimes graves e trilha para contravenções.', md5('Veteran or active duty military with service-connected issue. Felony track and misdemeanor track.')),
  ('specialty_courts', 5, 'notes', 'pt', 'O maior VTC da Califórnia. Parceria com o VA de West LA e várias organizações de apoio a veteranos (VSOs).', md5('Largest VTC in California. Partners with West LA VA and multiple VSOs.')),
  ('specialty_courts', 5, 'eligibility', 'vi', 'Cựu chiến binh hoặc quân nhân tại ngũ có vấn đề liên quan đến quá trình phục vụ. Có lộ trình trọng tội và lộ trình khinh tội.', md5('Veteran or active duty military with service-connected issue. Felony track and misdemeanor track.')),
  ('specialty_courts', 5, 'notes', 'vi', 'VTC lớn nhất California. Hợp tác với VA West LA và nhiều tổ chức phục vụ cựu chiến binh (VSO).', md5('Largest VTC in California. Partners with West LA VA and multiple VSOs.')),
  ('specialty_courts', 6, 'eligibility', 'es', 'Veterano o militar actual. Se requiere una condición de salud mental o de consumo de sustancias vinculada al servicio.', md5('Veteran or current military. Service-connected mental health or substance use condition required.')),
  ('specialty_courts', 6, 'notes', 'es', 'Arizona tiene una sólida red de VTC en todo el estado.', md5('Arizona has a strong VTC network statewide.')),
  ('specialty_courts', 6, 'eligibility', 'pt', 'Veterano ou militar atual. É exigida uma condição de saúde mental ou de uso de substâncias ligada ao serviço.', md5('Veteran or current military. Service-connected mental health or substance use condition required.')),
  ('specialty_courts', 6, 'notes', 'pt', 'O Arizona tem uma forte rede de VTCs em todo o estado.', md5('Arizona has a strong VTC network statewide.')),
  ('specialty_courts', 6, 'eligibility', 'vi', 'Cựu chiến binh hoặc quân nhân hiện tại. Cần có tình trạng sức khỏe tâm thần hoặc sử dụng chất liên quan đến quá trình phục vụ.', md5('Veteran or current military. Service-connected mental health or substance use condition required.')),
  ('specialty_courts', 6, 'notes', 'vi', 'Arizona có mạng lưới VTC mạnh trên toàn tiểu bang.', md5('Arizona has a strong VTC network statewide.')),
  ('specialty_courts', 7, 'eligibility', 'es', 'Veterano de Florida con una condición vinculada al servicio. Vías para delitos graves y delitos menores.', md5('Florida veteran with service-connected condition. Felony and misdemeanor tracks.')),
  ('specialty_courts', 7, 'notes', 'es', 'Colabora con la red del Hospital de Veteranos James A. Haley.', md5('Partners with James A. Haley Veterans Hospital network.')),
  ('specialty_courts', 7, 'eligibility', 'pt', 'Veterano da Flórida com uma condição ligada ao serviço. Trilhas para crimes graves e contravenções.', md5('Florida veteran with service-connected condition. Felony and misdemeanor tracks.')),
  ('specialty_courts', 7, 'notes', 'pt', 'Parceria com a rede do Hospital de Veteranos James A. Haley.', md5('Partners with James A. Haley Veterans Hospital network.')),
  ('specialty_courts', 7, 'eligibility', 'vi', 'Cựu chiến binh tại Florida có tình trạng liên quan đến quá trình phục vụ. Có lộ trình trọng tội và khinh tội.', md5('Florida veteran with service-connected condition. Felony and misdemeanor tracks.')),
  ('specialty_courts', 7, 'notes', 'vi', 'Hợp tác với mạng lưới Bệnh viện Cựu chiến binh James A. Haley.', md5('Partners with James A. Haley Veterans Hospital network.')),
  ('specialty_courts', 8, 'eligibility', 'es', 'Veterano con una condición vinculada al servicio. La mayoría de los cargos de delito grave y menor califican.', md5('Veteran with service-connected condition. Most felony and misdemeanor charges eligible.')),
  ('specialty_courts', 8, 'notes', 'es', 'Colabora con el Centro Médico del VA Jesse Brown. Enfocado en el área de Chicago.', md5('Partners with Jesse Brown VA Medical Center. Chicago area focus.')),
  ('specialty_courts', 8, 'eligibility', 'pt', 'Veterano com uma condição ligada ao serviço. A maioria das acusações de crime grave e contravenção se qualifica.', md5('Veteran with service-connected condition. Most felony and misdemeanor charges eligible.')),
  ('specialty_courts', 8, 'notes', 'pt', 'Parceria com o Centro Médico do VA Jesse Brown. Foco na região de Chicago.', md5('Partners with Jesse Brown VA Medical Center. Chicago area focus.')),
  ('specialty_courts', 8, 'eligibility', 'vi', 'Cựu chiến binh có tình trạng liên quan đến quá trình phục vụ. Hầu hết các cáo buộc trọng tội và khinh tội đều đủ điều kiện.', md5('Veteran with service-connected condition. Most felony and misdemeanor charges eligible.')),
  ('specialty_courts', 8, 'notes', 'vi', 'Hợp tác với Trung tâm Y tế VA Jesse Brown. Tập trung vào khu vực Chicago.', md5('Partners with Jesse Brown VA Medical Center. Chicago area focus.')),
  ('specialty_courts', 9, 'eligibility', 'es', 'Veterano o en servicio activo. Condición de salud mental o trastorno por consumo de sustancias vinculado al servicio.', md5('Veteran or active duty. Service-connected mental health condition or substance use disorder.')),
  ('specialty_courts', 9, 'notes', 'es', 'Con sede en Columbus. Colabora con el VAMC de Columbus.', md5('Columbus-based. Partners with Columbus VAMC.')),
  ('specialty_courts', 9, 'eligibility', 'pt', 'Veterano ou militar da ativa. Condição de saúde mental ou transtorno por uso de substâncias ligado ao serviço.', md5('Veteran or active duty. Service-connected mental health condition or substance use disorder.')),
  ('specialty_courts', 9, 'notes', 'pt', 'Sediado em Columbus. Parceria com o VAMC de Columbus.', md5('Columbus-based. Partners with Columbus VAMC.')),
  ('specialty_courts', 9, 'eligibility', 'vi', 'Cựu chiến binh hoặc quân nhân tại ngũ. Có tình trạng sức khỏe tâm thần hoặc rối loạn sử dụng chất liên quan đến quá trình phục vụ.', md5('Veteran or active duty. Service-connected mental health condition or substance use disorder.')),
  ('specialty_courts', 9, 'notes', 'vi', 'Đặt tại Columbus. Hợp tác với VAMC Columbus.', md5('Columbus-based. Partners with Columbus VAMC.')),
  ('specialty_courts', 10, 'eligibility', 'es', 'Veterano con una condición vinculada al servicio. Califican delitos graves y menores.', md5('Veteran with service-connected condition. Felony and misdemeanor eligible.')),
  ('specialty_courts', 10, 'notes', 'es', 'Colabora con los campus del VA de American Lake y Seattle.', md5('Partners with American Lake and Seattle VA campuses.')),
  ('specialty_courts', 10, 'eligibility', 'pt', 'Veterano com uma condição ligada ao serviço. Crimes graves e contravenções se qualificam.', md5('Veteran with service-connected condition. Felony and misdemeanor eligible.')),
  ('specialty_courts', 10, 'notes', 'pt', 'Parceria com os campi do VA de American Lake e Seattle.', md5('Partners with American Lake and Seattle VA campuses.')),
  ('specialty_courts', 10, 'eligibility', 'vi', 'Cựu chiến binh có tình trạng liên quan đến quá trình phục vụ. Trọng tội và khinh tội đều đủ điều kiện.', md5('Veteran with service-connected condition. Felony and misdemeanor eligible.')),
  ('specialty_courts', 10, 'notes', 'vi', 'Hợp tác với các cơ sở VA American Lake và Seattle.', md5('Partners with American Lake and Seattle VA campuses.')),
  ('specialty_courts', 11, 'eligibility', 'es', 'Delito grave o menor no violento relacionado con drogas. Sin antecedentes violentos. Debe tener un diagnóstico de trastorno por consumo de sustancias.', md5('Non-violent drug-related felony or misdemeanor. No violent history. Must have substance use disorder diagnosis.')),
  ('specialty_courts', 11, 'notes', 'es', 'Programa de supervisión intensiva de 18 a 24 meses. Comparecencias periódicas ante el tribunal, pruebas frecuentes y tratamiento.', md5('18-24 month intensive supervision program. Regular court appearances, frequent testing, treatment.')),
  ('specialty_courts', 11, 'eligibility', 'pt', 'Crime grave ou contravenção não violento relacionado a drogas. Sem histórico violento. Deve ter diagnóstico de transtorno por uso de substâncias.', md5('Non-violent drug-related felony or misdemeanor. No violent history. Must have substance use disorder diagnosis.')),
  ('specialty_courts', 11, 'notes', 'pt', 'Programa de supervisão intensiva de 18 a 24 meses. Comparecimentos regulares ao tribunal, testes frequentes e tratamento.', md5('18-24 month intensive supervision program. Regular court appearances, frequent testing, treatment.')),
